from taf.cloud.lcmaas.facade import LCMaaSConnection
from taf.internal.aliasing import aliasing_scope


class lcmaas(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('lcmaas_connection', LCMaaSConnection, name=__name__)
    """
        Usage example:
        >>> from taf.cloud.lcmaas import lcmaas
        >>> lcmaas_object = lcmaas()
        >>> lcmaas_object.connect_to(host='10.1.1.1', port='8443', lcmaas_version='lcmaas_v1',
        >>>                          username='lcm', password='system123', secure=True)
        >>> lcmaas_object.delete_vi()

    """

    def __init__(self):
        self.lookup_handler.store = self.store

    def connect_to(self, host, username, password, port=8443, lcmaas_version='lcmaas_v1', secure=True,
                   connection_name="default"):
        """
        Provides connection and jwt token to LCMaaS.

        :param str host: IP address to proper host, f.e. `127.0.0.1`.
        :param str username: Username to authenticate to LCMaaS.
        :param str password: Password to authenticate to LCMaaS.
        :param str port: Port for connection to LCMaaS.
        :param str lcmaas_version: The LCMaaS API version. Set to the newest by default.
                                   Available releases now: lcmaas_v1. If user expects from the library that interface
                                   is stable, always specify release version in your code.
        :param boolean secure: Default `True`. If set to `False`, the connection will be realized with use http prefix,
                               else with https.
        :param str connection_name: (Optional) Name of returned connection. It not provided, this connection becomes default.
        :return: LCMaaSConnection object.
        """
        lcmaas_connection = LCMaaSConnection(host=host,
                                             username=username,
                                             password=password,
                                             port=port,
                                             lcmaas_version=lcmaas_version,
                                             secure=secure)
        self.store.add(lcmaas_connection, connection_name)
        return lcmaas_connection

    @lookup_handler.implicit_lookup
    def get_dpps(self, group=None, lcmaas_connection=None):
        """
        get all of the dpps information.

        :param str group: (Optional) group of dpp, default is None.
        :param Union[LCMaaSConnection,str] lcmaas_connection: (Optional) LCMaaSConnection object or string name alias if used
        :return list: list with DPPs information per DPP, f.g.:
                      [
                          {
                            "dpp_name": "string",
                            "dpp_group": "string",
                            "dpp_status": "New",
                            "dpp_process": "string",
                            "cnf_package": "vDU_0.300.4979",
                            "cnf_instance": {
                              "cnf_instance_name": "string",
                              "vi_name": "string",
                              "prepare_releases": [
                                {
                                  "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                                }
                              ],
                              "main_release": {
                                "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                              },
                              "overrides": [
                                              {
                                                "chart": "string",
                                                "override_value": "string"
                                              }
                                            ],
                              "cnf_package": "string"
                            }
                          }
                        ]
        """
        return [dpp_info.to_dict() for dpp_info in lcmaas_connection.get_dpps(group)]

