    def get_dpp_by_name(self, dpp_name, lcmaas_connection=None):
        """
        Get dpp information by giving the dpp name.

        :param str dpp_name: dpp name
        :param Union[LCMaaSConnection,str] lcmaas_connection: (Optional) LCMaaSConnection object or string name alias if used
        :return dict: dict of DPP information, f.g.:
                      {
                            "dpp_name": "string",
                            "dpp_group": "string",
                            "dpp_status": "New",
                            "dpp_process": "string",
                            "cnf_package": "vDU_0.300.4979",
                            "cnf_instance": {
                              "cnf_instance_name": "string",
                              "vi_name": "string",
                              "prepare_releases": [
                                {
                                  "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                                }
                              ],
                              "main_release": {
                                "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                              },
                              "overrides": [
                                              {
                                                "chart": "string",
                                                "override_value": "string"
                                              }
                                            ],
                              "cnf_package": "string"
                            }
                          }
        """
        return lcmaas_connection.get_dpp_by_name(dpp_name=dpp_name).to_dict()

    @lookup_handler.implicit_lookup
    def create_dpp(self, dpp_name, cnf_pkg_name, cnf_instance_name, vi_name, namespace,
                   chart_override_mapping=None, dpp_group=None, lcmaas_connection=None):
        """
        create a DPP.

        :param str dpp_name: the name of DPP.
        :param str cnf_pkg_name: Name of the CNF package.
        :param str cnf_instance_name: Name of CNF instance.
        :param str vi_name: Name of VI.
        :param str namespace: Namespace scope for Dpp deploy.
        :param list chart_override_mapping: (Optional) a set of extra Values added to the chart, default is None, f.g:
                                           [{'aic-vdu-prerequisite-0.300.2580':'path of override yaml file'},
                                            {'aic-vdu-0.300.2580':'path of override yaml file'}]
        :param str dpp_group: (Optional) dpp group, default is None.
        :param Union[LCMaaSConnection,str] lcmaas_connection: (Optional) LCMaaSConnection object or string name alias if used
        :return dict: dict of DPP information, f.g.:
                      {
                            "dpp_name": "string",
                            "dpp_group": "string",
                            "dpp_status": "New",
                            "dpp_process": "string",
                            "cnf_package": "vDU_0.300.4979",
                            "cnf_instance": {
                              "cnf_instance_name": "string",
                              "vi_name": "string",
                              "prepare_releases": [
                                {
                                  "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                                }
                              ],
                              "main_release": {
                                "release_name": "string",
                                  "helm_chart": "string",
                                  "release_version": 0,
                                  "release_status": "string",
                                  "release_ns": "string",
                                  "override_values": "string"
                              },
                              "overrides": [
                                              {
                                                "chart": "string",
                                                "override_value": "string"
                                              }
                                            ],
                              "cnf_package": "string"
                            }
                          }
        """
        return lcmaas_connection.create_dpp(dpp_name=dpp_name,
                                            cnf_pkg_name=cnf_pkg_name,
                                            cnf_instance_name=cnf_instance_name,
                                            vi_name=vi_name,
                                            namespace=namespace,
                                            chart_override_mapping=chart_override_mapping,
                                            dpp_group=dpp_group).to_dict()

    @lookup_handler.implicit_lookup
    def delete_dpp(self, dpp_name, lcmaas_connection=None):
        """
        delete a given dpp.

        :param str dpp_name: Name of DPP.
        :param Union[LCMaaSConnection,str] lcmaas_connection: (Optional) LCMaaSConnection object or string name alias if used
        :return: None
        """
        return lcmaas_connection.delete_dpp(dpp_name=dpp_name)

