    @lookup_handler.implicit_lookup
    def install_certs(self, peer_name, peer_type, cert_content, lcmaas_connection=None):
        """
        install certificate(s)

        :param str peer_name: the peer name, like VI name or NEAT name.
        :param str peer_type: Peer type for which the certificate is installed, can be one of [ NEAT, VI, SELF ].
        :param str cert_content: Certificate Content With PEM Format
        :param Union[LCMaaSConnection,str] lcmaas_connection: (optional) LCMaaSConnection object or string name alias if used
        :return list: list of certs information. like:
                      [
                          {
                            "cert_name": "string",
                            "peer_type": "NEAT",
                            "peer_name": "string",
                            "cert_type": "CA",
                            "cert_content": "string"
                          }
                        ]
        """
        certs_info = lcmaas_connection.install_certs(peer_type=peer_type,
                                                     peer_name=peer_name,
                                                     cert_content=cert_content)
        return [cert_info.to_dict() for cert_info in certs_info]

    @lookup_handler.implicit_lookup
    def create_cnf_package(self, cnf_pkg_name, cnf_pkg_url, lcmaas_connection=None):
        """
        Create a CNF package.

        :param str cnf_pkg_name: Name of the CNF package, it should satisfy the pattern: ^[A-Za-z][A-Za-z0-9_.]*$
        :param str cnf_pkg_url: URL of CNF package from where it could downloaded.
        :param Union[LCMaaSConnection,str] lcmaas_connection: LCMaaSConnection object or string name alias if used
        :return dict: the CNF package info, f.g:
                      {
                            "cnf_pkg_name": "string",
                            "status": "Creating, Created, Error, Deleting",
                            "cnf_pkg_url": "string",
                            "chart_info": [{"chart_name": "string",
                                           "chart_version": "1.0.0",
                                           "api_version": "v2",
                                           "app_version": "1.1.0"}]
                      }
        """
        return lcmaas_connection.create_cnf_package(cnf_pkg_name=cnf_pkg_name, cnf_pkg_url=cnf_pkg_url).to_dict()

